-- 0003_w5t07_dust_chunks (M1-W5-T07). Dust chunk rows, two alternating versions per chunk (data-model.md section 3.7b).
-- Written by the solo checkpoint upload (apps/server/src/persistence) and, later, by the room checkpoints (M1-W5-T01).
-- Generated by drizzle-kit, then amended by hand BEFORE merge in two ways (same two amendments as 0001):
--   1. the foreign-key target is not qualified with the "public" schema, so the migration follows search_path
--      (prod | staging | _aN); migrate.test.ts fails the build if a migration mentions it.
--   2. the trailing ALTER sets blob to EXTERNAL storage: the payload is already deflate-compressed, so PostgreSQL must
--      not spend CPU trying to pglz it again.
-- Expand step only: a new table, so code from before this migration keeps working. No secondary index: rows are always
-- addressed by (contract_id, chunk_id, ver) through the primary key (at most 641 * 2 rows per Contract, loaded by the
-- contract_id prefix of that key). Forward-only; never edit after merge.
CREATE TABLE "contract_dust_chunks" (
	"contract_id" uuid NOT NULL,
	"chunk_id" smallint NOT NULL,
	"ver" smallint NOT NULL,
	"save_seq" bigint NOT NULL,
	"codec" text NOT NULL,
	"raw_size" integer NOT NULL,
	"blob_size" integer NOT NULL,
	"checksum" integer NOT NULL,
	"blob" "bytea" NOT NULL,
	"saved_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "contract_dust_chunks_pk" PRIMARY KEY("contract_id","chunk_id","ver"),
	CONSTRAINT "contract_dust_chunks_chunk_id_check" CHECK ("contract_dust_chunks"."chunk_id" between 0 and 640),
	CONSTRAINT "contract_dust_chunks_ver_check" CHECK ("contract_dust_chunks"."ver" in (0, 1))
);
